1	#!/usr/bin/env node
2	// Prov Guard —— 软件供应链证明与完整性校验工具（零依赖，Node >= 18）。
3	//
4	// 子命令：
5	//   keygen   --key-dir <dir> [--name <prefix>]
6	//   generate --artifact <path> --key <private-key> --out <dir>
7	//   verify   --artifact <path> --proof <file> --signature <file> --key <public-key>
8	//            [--sbom <file> --sbom-signature <file>]
9	//
10	// 所有输出均为 UTF-8；成功结果写 stdout，错误结果写 stderr。
11	
12	import {
13	  createHash,
14	  createPrivateKey,
15	  createPublicKey,
16	  generateKeyPairSync,
17	  sign as cryptoSign,
18	  verify as cryptoVerify,
19	} from 'node:crypto';
20	import { constants as fsConstants, readFileSync, realpathSync } from 'node:fs';
21	import { access, mkdir, readdir, readFile, realpath, rename, rm, stat, writeFile } from 'node:fs/promises';
22	import { basename, dirname, isAbsolute, join, relative, resolve, sep } from 'node:path';
23	import { fileURLToPath } from 'node:url';
24	
25	export const PROOF_VERSION = '1.0';
26	
27	// ---------------------------------------------------------------------------
28	// 错误类型：携带机器可读错误码，CLI 边界统一转换为非零退出。
29	// ---------------------------------------------------------------------------
30	
31	export const ERROR_CODES = Object.freeze({
32	  INPUT_NOT_FOUND: 'INPUT_NOT_FOUND',
33	  PERMISSION_DENIED: 'PERMISSION_DENIED',
34	  PROOF_INVALID: 'PROOF_INVALID',
35	  SIGNATURE_INVALID: 'SIGNATURE_INVALID',
36	  KEY_NOT_FOUND: 'KEY_NOT_FOUND',
37	  INTEGRITY_MISMATCH: 'INTEGRITY_MISMATCH',
38	  USAGE_ERROR: 'USAGE_ERROR',
39	});
40	
41	class ProvError extends Error {
42	  constructor(code, message, details) {
43	    super(message);
44	    this.name = 'ProvError';
45	    this.code = code;
46	    if (details !== undefined) this.details = details;
47	  }
48	}
49	
50	// 把 Node 底层错误归类为 INPUT_NOT_FOUND / PERMISSION_DENIED，其余原样抛出。
51	function wrapFsError(err, context) {
52	  if (err instanceof ProvError) return err;
53	  const where = context ? `${context}: ` : '';
54	  if (err && err.code === 'ENOENT') {
55	    return new ProvError(ERROR_CODES.INPUT_NOT_FOUND, `${where}路径不存在 (${err.path || 'unknown path'})`);
56	  }
57	  if (err && (err.code === 'EACCES' || err.code === 'EPERM')) {
58	    return new ProvError(ERROR_CODES.PERMISSION_DENIED, `${where}权限不足 (${err.path || 'unknown path'})`);
59	  }
60	  return err;
61	}
62	
63	// ---------------------------------------------------------------------------
64	// 路径与摘要工具
65	// ---------------------------------------------------------------------------
66	
67	// 清单中的相对路径统一使用正斜杠，保证跨平台稳定。
68	export function toPosix(relPath) {
69	  return relPath.split(sep).join('/');
70	}
71	
72	// 稳定哈希：SHA-256，摘要对象按 key 排序后以 UTF-8 序列化（两空格缩进）。
73	export function stableJsonStringify(value) {
74	  return JSON.stringify(sortDeep(value), null, 2);
75	}
76	
77	function sortDeep(value) {
78	  if (Array.isArray(value)) return value.map(sortDeep);
79	  if (value !== null && typeof value === 'object') {
80	    const out = {};
81	    for (const key of Object.keys(value).sort()) out[key] = sortDeep(value[key]);
82	    return out;
83	  }
84	  return value;
85	}
86	
87	export function sha256Hex(data) {
88	  return createHash('sha256').update(data).digest('hex');
89	}
90	
91	// 公钥指纹：对 SPKI 编码的 DER 字节取 SHA-256。写入证明并随证明一起签名，
92	// 验证时据此区分“使用了错误公钥”（指纹不一致）与“签名内容被篡改”（指纹一致但验签失败）。
93	export function keyFingerprint(keyObj) {
94	  return sha256Hex(keyObj.export({ type: 'spki', format: 'der' }));
95	}
96	
97	// ---------------------------------------------------------------------------
98	// 产物扫描：递归列出全部常规文件（含符号链接解引用后的目标），
99	// 空目录自然产生空清单；零字节文件按真实文件记录。
100	// ---------------------------------------------------------------------------
101	
102	async function walkFiles(rootDir) {
103	  const found = [];
104	  async function walk(dir) {
105	    let entries;
106	    try {
107	      entries = await readdir(dir, { withFileTypes: true });
108	    } catch (err) {
109	      throw wrapFsError(err, '读取产物目录');
110	    }
111	    for (const entry of entries) {
112	      const full = join(dir, entry.name);
113	      if (entry.isDirectory()) {
114	        await walk(full);
115	      } else if (entry.isFile()) {
116	        found.push(full);
117	      } else if (entry.isSymbolicLink()) {
118	        // 解引用后按目标类型处理：指向目录则继续递归，指向文件则记录。
119	        let target;
120	        try {
121	          target = await stat(full);
122	        } catch (err) {
123	          throw wrapFsError(err, '读取符号链接');
124	        }
125	        if (target.isDirectory()) await walk(full);
126	        else if (target.isFile()) found.push(full);
127	      }
128	      // 其他特殊文件（套接字/设备等）忽略。
129	    }
130	  }
131	  await walk(rootDir);
132	  return found;
133	}
134	
135	// 判断 root 是否位于 outDir 之内（用于从扫描结果排除输出目录自身）。
136	function isWithin(pathAbs, dirAbs) {
137	  const relPath = relative(dirAbs, pathAbs);
138	  return relPath === '' || (!!relPath && !relPath.startsWith('..') && !isAbsolute(relPath));
139	}
140	
141	async function fileTypeFromPath(fullPath, data) {
142	  // 极简魔数嗅探，仅用于清单的 type 字段；不识别时回退为扩展名或 "data"。
143	  // 一律使用字节数组，避免多字节字符串经 UTF-8 编码后长度/取值不符。
144	  const startsWith = (bytes) =>
145	    data.length >= bytes.length && bytes.every((b, i) => data[i] === b);
146	  if (startsWith([0x1f, 0x8b])) return 'application/gzip';
147	  if (startsWith([0x50, 0x4b, 0x03, 0x04])) return 'application/zip';
148	  if (startsWith([0x25, 0x50, 0x44, 0x46, 0x2d])) return 'application/pdf'; // %PDF-
149	  if (startsWith([0x7f, 0x45, 0x4c, 0x46])) return 'application/x-elf';
150	  if (startsWith([0x4d, 0x5a])) return 'application/x-dosexec'; // MZ
151	  if (startsWith([0xff, 0xd8, 0xff])) return 'image/jpeg';
152	  if (startsWith([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])) return 'image/png';
153	  // 类脚本/文本：UTF BOM，或前 512 字节不含 NUL 则视为 text。
154	  if (
155	    startsWith([0xef, 0xbb, 0xbf]) ||
156	    startsWith([0xff, 0xfe]) ||
157	    startsWith([0xfe, 0xff])
158	  ) {
159	    return 'text/plain';
160	  }
161	  if (!data.subarray(0, 512).includes(0)) return 'text/plain';
162	  const ext = basename(fullPath).split('.').pop();
163	  return ext && ext !== basename(fullPath) ? `application/x-${ext.toLowerCase()}` : 'application/octet-stream';
164	}
165	
166	// 构建 SBOM。时间字段不进入清单，文件摘要只依赖文件字节与相对路径。
167	// excludeDir 为输出目录的绝对路径（若位于产物内部则排除）。
168	export async function buildSbom(artifactPath, excludeDir) {
169	  const artifactAbs = resolve(artifactPath);
170	  let artifactStat;
171	  try {
172	    artifactStat = await stat(artifactAbs);
173	  } catch (err) {
174	    throw wrapFsError(err, '读取产物');
175	  }
176	
177	  const rootDir = artifactStat.isDirectory() ? artifactAbs : dirname(artifactAbs);
178	  const excludeAbs = excludeDir ? resolve(excludeDir) : null;
179	
180	  let files;
181	  if (artifactStat.isDirectory()) {
182	    files = await walkFiles(artifactAbs);
183	  } else {
184	    files = [artifactAbs];
185	  }
186	
187	  const entries = [];
188	  for (const full of files) {
189	    if (excludeAbs && isWithin(full, excludeAbs)) continue;
190	    let data;
191	    try {
192	      data = await readFile(full);
193	    } catch (err) {
194	      throw wrapFsError(err, '读取产物文件');
195	    }
196	    const relPath = toPosix(relative(rootDir, full));
197	    entries.push({
198	      path: relPath,
199	      sha256: sha256Hex(data),
200	      size: data.length,
201	      type: await fileTypeFromPath(full, data),
202	    });
203	  }
204	
205	  // 按相对路径排序，保证同一输入产生字节级一致的清单。
206	  entries.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
207	
208	  return {
209	    schemaVersion: '1.0',
210	    artifactName: artifactStat.isDirectory() ? basename(artifactAbs) : basename(artifactAbs),
211	    rootType: artifactStat.isDirectory() ? 'directory' : 'file',
212	    files: entries,
213	  };
214	}
215	
216	// 顶层产物摘要：对“排序后的文件条目列表”做稳定哈希。
217	// 任何字节变化、文件新增/删除/重命名都会改变该摘要。
218	export function computeArtifactDigest(sbom) {
219	  return sha256Hex(stableJsonStringify(sbom.files));
220	}
221	
222	// ---------------------------------------------------------------------------
223	// 密钥与签名（Ed25519，PEM）
224	// ---------------------------------------------------------------------------
225	
226	function readPrivateKey(keyPath) {
227	  let pem;
228	  try {
229	    pem = readFileSync(keyPath);
230	  } catch (err) {
231	    throw wrapFsError(err, '读取私钥');
232	  }
233	  let keyObj;
234	  try {
235	    keyObj = createPrivateKey({ key: pem, format: 'pem' });
236	  } catch {
237	    throw new ProvError(ERROR_CODES.KEY_NOT_FOUND, `私钥无法解析或格式不受支持: ${keyPath}`);
238	  }
239	  if (keyObj.asymmetricKeyType !== 'ed25519') {
240	    throw new ProvError(
241	      ERROR_CODES.KEY_NOT_FOUND,
242	      `私钥类型不是 Ed25519（实际为 ${keyObj.asymmetricKeyType}）: ${keyPath}`,
243	    );
244	  }
245	  return keyObj;
246	}
247	
248	function readPublicKey(keyPath) {
249	  let pem;
250	  try {
251	    pem = readFileSync(keyPath);
252	  } catch (err) {
253	    throw wrapFsError(err, '读取公钥');
254	  }
255	  let keyObj;
256	  try {
257	    keyObj = createPublicKey({ key: pem, format: 'pem' });
258	  } catch {
259	    throw new ProvError(ERROR_CODES.KEY_NOT_FOUND, `公钥无法解析或格式不受支持: ${keyPath}`);
260	  }
261	  if (keyObj.asymmetricKeyType !== 'ed25519') {
262	    throw new ProvError(
263	      ERROR_CODES.KEY_NOT_FOUND,
264	      `公钥类型不是 Ed25519（实际为 ${keyObj.asymmetricKeyType}）: ${keyPath}`,
265	    );
266	  }
267	  return keyObj;
268	}
269	
270	// 生成阶段时间戳采用 UTC ISO-8601；它只写入 proof，不参与任何摘要。
271	function nowIso() {
272	  return new Date().toISOString();
273	}
274	
275	// ---------------------------------------------------------------------------
276	// keygen
277	// ---------------------------------------------------------------------------
278	
279	export async function keygen({ keyDir, name = 'provguard' }) {
280	  const absDir = resolve(keyDir);
281	  try {
282	    await mkdir(absDir, { recursive: true });
283	  } catch (err) {
284	    throw wrapFsError(err, '创建密钥目录');
285	  }
286	  const { publicKey, privateKey } = generateKeyPairSync('ed25519');
287	  const privPath = join(absDir, `${name}.private.pem`);
288	  const pubPath = join(absDir, `${name}.public.pem`);
289	  try {
290	    await writeFile(
291	      privPath,
292	      privateKey.export({ type: 'pkcs8', format: 'pem' }),
293	      { mode: 0o600 },
294	    );
295	    await writeFile(
296	      pubPath,
297	      publicKey.export({ type: 'spki', format: 'pem' }),
298	      { mode: 0o644 },
299	    );
300	  } catch (err) {
301	    throw wrapFsError(err, '写入密钥');
302	  }
303	  return { privateKeyPath: privPath, publicKeyPath: pubPath };
304	}
305	
306	// ---------------------------------------------------------------------------
307	// generate
308	// ---------------------------------------------------------------------------
309	
310	export async function generate({ artifact, key, out }) {
311	  // 输入检查：产物与私钥必须存在且可读。
312	  const artifactAbs = resolve(artifact);
313	  const keyAbs = resolve(key);
314	  for (const [p, label] of [
315	    [artifactAbs, '产物'],
316	    [keyAbs, '私钥'],
317	  ]) {
318	    try {
319	      await access(p, fsConstants.R_OK);
320	    } catch (err) {
321	      throw wrapFsError(err, `读取${label}`);
322	    }
323	  }
324	
325	  const outAbs = resolve(out);
326	  const parent = dirname(outAbs);
327	  try {
328	    await mkdir(parent, { recursive: true });
329	  } catch (err) {
330	    throw wrapFsError(err, '创建输出目录');
331	  }
332	
333	  // 若输出目录尚不存在，先按真实路径创建，再据此排除。
334	  try {
335	    await mkdir(outAbs, { recursive: true });
336	  } catch (err) {
337	    throw wrapFsError(err, '创建输出目录');
338	  }
339	  let outReal;
340	  try {
341	    outReal = await realpath(outAbs);
342	  } catch (err) {
343	    throw wrapFsError(err, '解析输出目录');
344	  }
345	
346	  const privateKey = readPrivateKey(keyAbs);
347	  // 由私钥导出对应公钥，记录其指纹到证明中，供验证区分错误公钥与签名失配。
348	  const signingPublicKey = createPublicKey(privateKey);
349	  const signerKeyFingerprint = keyFingerprint(signingPublicKey);
350	
351	  const sbom = await buildSbom(artifactAbs, outReal);
352	  const artifactDigest = computeArtifactDigest(sbom);
353	
354	  // SBOM 规范字节：稳定 JSON（去尾换行后的 UTF-8）。proof 中的 sbomDigest 与
355	  // sbom.json.sig 绑定同一组字节，防止证明有效而 sbom.json 被整体替换。
356	  const sbomCanonical = stableJsonStringify(sbom);
357	  const sbomDigest = sha256Hex(sbomCanonical);
358	
359	  const proof = {
360	    proofVersion: PROOF_VERSION,
361	    artifactName: basename(artifactAbs),
362	    artifactDigest,
363	    fileName: basename(artifactAbs),
364	    size: sbom.files.reduce((n, f) => n + f.size, 0),
365	    generatedAt: nowIso(),
366	    signerKeyFingerprint,
367	    sbomDigest,
368	    files: sbom.files,
369	  };
370	  // 稳定字段顺序：proof 先按既定顺序构造，再整体排序输出。
371	  const proofJson = stableJsonStringify(proof) + '\n';
372	  const sbomJson = sbomCanonical + '\n';
373	
374	  // 对证明的规范字节（不含尾部换行）签名，验证时使用同一规范形式。
375	  // Ed25519 为纯签名算法，不接受摘要算法参数，故用 sign(null, data, key)。
376	  const signature = cryptoSign(null, Buffer.from(proofJson.trimEnd(), 'utf8'), privateKey);
377	  const signatureB64 = signature.toString('base64') + '\n';
378	  // 对 SBOM 规范字节单独签名，Base64 加换行保存。
379	  const sbomSignature = cryptoSign(null, Buffer.from(sbomCanonical, 'utf8'), privateKey);
380	  const sbomSignatureB64 = sbomSignature.toString('base64') + '\n';
381	
382	  const proofPath = join(outReal, 'proof.json');
383	  const sbomPath = join(outReal, 'sbom.json');
384	  const sigPath = join(outReal, 'proof.json.sig');
385	  const sbomSigPath = join(outReal, 'sbom.json.sig');
386	  try {
387	    await atomicWrite(proofPath, proofJson);
388	    await atomicWrite(sbomPath, sbomJson);
389	    await atomicWrite(sigPath, signatureB64);
390	    await atomicWrite(sbomSigPath, sbomSignatureB64);
391	  } catch (err) {
392	    throw wrapFsError(err, '写入证明产物');
393	  }
394	
395	  return {
396	    proofPath,
397	    sbomPath,
398	    signaturePath: sigPath,
399	    sbomSignaturePath: sbomSigPath,
400	    artifactDigest,
401	    sbomDigest,
402	    fileCount: sbom.files.length,
403	    proofVersion: PROOF_VERSION,
404	  };
405	}
406	
407	// 同目录临时文件 + rename，避免半成品证明文件留在输出目录。
408	async function atomicWrite(target, contents) {
409	  const dir = dirname(target);
410	  const tmp = join(dir, `.${basename(target)}.${process.pid}.tmp`);
411	  await writeFile(tmp, contents, { mode: 0o644 });
412	  try {
413	    await rename(tmp, target);
414	  } catch (err) {
415	    await rm(tmp, { force: true });
416	    throw err;
417	  }
418	}
419	
420	// ---------------------------------------------------------------------------
421	// verify
422	// ---------------------------------------------------------------------------
423	
424	export async function verify({
425	  artifact,
426	  proof: proofPath,
427	  signature: sigPath,
428	  key: pubKeyPath,
429	  sbom: sbomPath,
430	  sbomSignature: sbomSigPath,
431	}) {
432	  const artifactAbs = resolve(artifact);
433	  const proofAbs = resolve(proofPath);
434	  const sigAbs = resolve(sigPath);
435	  const keyAbs = resolve(pubKeyPath);
436	
437	  // --sbom 与 --sbom-signature 必须成对出现；只给一者是用法错误。
438	  const sbomMode = sbomPath !== undefined || sbomSigPath !== undefined;
439	  if (sbomMode && (sbomPath === undefined || sbomSigPath === undefined)) {
440	    throw new ProvError(ERROR_CODES.USAGE_ERROR, '--sbom 与 --sbom-signature 必须成对提供');
441	  }
442	  const sbomAbs = sbomMode ? resolve(sbomPath) : null;
443	  const sbomSigAbs = sbomMode ? resolve(sbomSigPath) : null;
444	
445	  // 1) 所有输入必须存在且可读。
446	  const inputs = [
447	    [artifactAbs, '产物'],
448	    [proofAbs, '证明文件'],
449	    [sigAbs, '签名文件'],
450	    [keyAbs, '公钥'],
451	  ];
452	  if (sbomMode) {
453	    inputs.push([sbomAbs, 'SBOM 文件'], [sbomSigAbs, 'SBOM 签名文件']);
454	  }
455	  for (const [p, label] of inputs) {
456	    try {
457	      await access(p, fsConstants.R_OK);
458	    } catch (err) {
459	      throw wrapFsError(err, `读取${label}`);
460	    }
461	  }
462	
463	  // 2) 公钥必须可解析且为 Ed25519 —— 错误/不支持的公钥归 KEY_NOT_FOUND。
464	  const publicKey = readPublicKey(keyAbs);
465	
466	  // 3) 证明文件必须是可解析的 JSON 且结构合法 —— 否则 PROOF_INVALID。
467	  let proofText;
468	  try {
469	    proofText = await readFileUtf8(proofAbs);
470	  } catch (err) {
471	    throw wrapFsError(err, '读取证明文件');
472	  }
473	  let proof;
474	  try {
475	    proof = JSON.parse(proofText);
476	  } catch {
477	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '证明文件不是合法的 JSON');
478	  }
479	  const proofError = validateProof(proof);
480	  if (proofError) {
481	    throw new ProvError(ERROR_CODES.PROOF_INVALID, proofError);
482	  }
483	
484	  // 4) 签名文件必须是合法 Base64 且长度符合 Ed25519（64 字节）—— 否则 PROOF_INVALID。
485	  const sigText = await readFileUtf8(sigAbs);
486	  const sigB64 = sigText.replace(/\s+/g, '');
487	  let sigBuf;
488	  if (!/^[A-Za-z0-9+/]*={0,2}$/.test(sigB64) || sigB64.length === 0) {
489	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '签名文件不是合法的 Base64 内容');
490	  }
491	  try {
492	    sigBuf = Buffer.from(sigB64, 'base64');
493	  } catch {
494	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '签名文件无法解码为字节');
495	  }
496	  if (sigBuf.length !== 64) {
497	    throw new ProvError(
498	      ERROR_CODES.PROOF_INVALID,
499	      `签名长度非法（Ed25519 应为 64 字节，实际 ${sigBuf.length} 字节）`,
500	    );
501	  }
502	
503	  // 5) 重算证明的规范字节并验签。
504	  //    以磁盘上的 proof.json 原样为真，重新序列化其解析结果用于验签；
505	  //    generate 写出的即为稳定规范形式，因此往返一致。
506	  //
507	  //    错误归类（三者互不相同）：
508	  //      - 提供的公钥与证明中记录的签钥指纹不一致  -> KEY_NOT_FOUND（错误公钥）
509	  //      - 公钥一致但签名验证失败                  -> SIGNATURE_INVALID（签名内容不匹配）
510	  //      - 签名文件本身格式非法（前面）            -> PROOF_INVALID
511	  const providedFingerprint = keyFingerprint(publicKey);
512	  if (providedFingerprint.toLowerCase() !== proof.signerKeyFingerprint.toLowerCase()) {
513	    throw new ProvError(
514	      ERROR_CODES.KEY_NOT_FOUND,
515	      '提供的公钥与证明记录的签名密钥不一致（可能使用了错误公钥）',
516	      {
517	        providedKeyFingerprint: providedFingerprint,
518	        proofKeyFingerprint: proof.signerKeyFingerprint,
519	      },
520	    );
521	  }
522	
523	  const canonicalProof = stableJsonStringify(proof);
524	  let sigOk = false;
525	  try {
526	    sigOk = cryptoVerify(null, Buffer.from(canonicalProof, 'utf8'), publicKey, sigBuf);
527	  } catch {
528	    sigOk = false;
529	  }
530	  if (!sigOk) {
531	    throw new ProvError(
532	      ERROR_CODES.SIGNATURE_INVALID,
533	      '签名与证明内容不匹配（证明可能被改动，或签名已损坏）',
534	    );
535	  }
536	
537	  // 6) 签名通过后重新扫描产物并逐项比对 —— 任何差异均为 INTEGRITY_MISMATCH。
538	  //    排除输出目录：证明/签名/清单通常与产物相邻，验证时不得把它们计入产物。
539	  const excludeDir = inferExcludeDir(proofAbs, artifactAbs);
540	  const currentSbom = await buildSbom(artifactAbs, excludeDir);
541	  const currentDigest = computeArtifactDigest(currentSbom);
542	
543	  const mismatches = diffManifest(proof, currentSbom, currentDigest);
544	  if (mismatches.length > 0) {
545	    throw new ProvError(
546	      ERROR_CODES.INTEGRITY_MISMATCH,
547	      `检测到 ${mismatches.length} 处完整性差异`,
548	      { mismatches },
549	    );
550	  }
551	
552	  // 7) SBOM 模式：校验 sbom.json 结构、proof.sbomDigest、SBOM 签名，
553	  //    并确认 SBOM 清单与证明清单（进而与当前扫描）逐项一致。
554	  let sbomDigest;
555	  if (sbomMode) {
556	    sbomDigest = await verifySbom({ sbomAbs, sbomSigAbs, proof, publicKey });
557	  }
558	
559	  const result = {
560	    status: 'VERIFIED',
561	    proofVersion: proof.proofVersion,
562	    artifactDigest: currentDigest,
563	    fileCount: currentSbom.files.length,
564	  };
565	  if (sbomMode) result.sbomDigest = sbomDigest;
566	  return result;
567	}
568	
569	// SBOM 校验：结构 -> 摘要 -> 签名 -> 清单一致性。
570	async function verifySbom({ sbomAbs, sbomSigAbs, proof, publicKey }) {
571	  // a) sbom.json 必须是可解析的 JSON 且结构合法 —— 否则 PROOF_INVALID。
572	  const sbomText = await readFileUtf8(sbomAbs);
573	  let sbom;
574	  try {
575	    sbom = JSON.parse(sbomText);
576	  } catch {
577	    throw new ProvError(ERROR_CODES.PROOF_INVALID, 'SBOM 文件不是合法的 JSON');
578	  }
579	  const sbomError = validateSbom(sbom);
580	  if (sbomError) {
581	    throw new ProvError(ERROR_CODES.PROOF_INVALID, sbomError);
582	  }
583	
584	  // b) 证明必须携带合法的 sbomDigest 字段。
585	  if (typeof proof.sbomDigest !== 'string' || !/^[0-9a-f]{64}$/i.test(proof.sbomDigest)) {
586	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '证明缺少合法的 sbomDigest 字段');
587	  }
588	
589	  // c) 重算 SBOM 规范字节摘要并与证明比对 —— 不一致说明 sbom.json 被替换或改动。
590	  const canonicalSbom = stableJsonStringify(sbom);
591	  const recomputed = sha256Hex(canonicalSbom);
592	  if (recomputed.toLowerCase() !== proof.sbomDigest.toLowerCase()) {
593	    throw new ProvError(
594	      ERROR_CODES.INTEGRITY_MISMATCH,
595	      'sbom.json 与证明记录的 sbomDigest 不一致（SBOM 可能被替换）',
596	      { mismatches: [{ path: 'sbom.json', kind: 'content-modified' }] },
597	    );
598	  }
599	
600	  // d) SBOM 签名：合法 Base64 且 64 字节 —— 否则 PROOF_INVALID；验签失败 SIGNATURE_INVALID。
601	  const sigText = await readFileUtf8(sbomSigAbs);
602	  const sigB64 = sigText.replace(/\s+/g, '');
603	  if (!/^[A-Za-z0-9+/]*={0,2}$/.test(sigB64) || sigB64.length === 0) {
604	    throw new ProvError(ERROR_CODES.PROOF_INVALID, 'SBOM 签名文件不是合法的 Base64 内容');
605	  }
606	  const sigBuf = Buffer.from(sigB64, 'base64');
607	  if (sigBuf.length !== 64) {
608	    throw new ProvError(
609	      ERROR_CODES.PROOF_INVALID,
610	      `SBOM 签名长度非法（Ed25519 应为 64 字节，实际 ${sigBuf.length} 字节）`,
611	    );
612	  }
613	  let sigOk = false;
614	  try {
615	    sigOk = cryptoVerify(null, Buffer.from(canonicalSbom, 'utf8'), publicKey, sigBuf);
616	  } catch {
617	    sigOk = false;
618	  }
619	  if (!sigOk) {
620	    throw new ProvError(
621	      ERROR_CODES.SIGNATURE_INVALID,
622	      'SBOM 签名与 sbom.json 内容不匹配（SBOM 可能被改动，或签名已损坏）',
623	    );
624	  }
625	
626	  // e) SBOM 清单与证明清单逐项一致（证明与当前扫描已在前面比对，故三方一致）。
627	  const mismatches = diffSbomAgainstProof(sbom, proof);
628	  if (mismatches.length > 0) {
629	    throw new ProvError(
630	      ERROR_CODES.INTEGRITY_MISMATCH,
631	      `SBOM 与证明清单存在 ${mismatches.length} 处差异`,
632	      { mismatches },
633	    );
634	  }
635	
636	  return recomputed;
637	}
638	
639	function inferExcludeDir(proofAbs, artifactAbs) {
640	  // 证明文件所在目录若位于产物之内，则将其视为生成时的输出目录予以排除。
641	  const proofDir = dirname(proofAbs);
642	  if (isWithin(proofDir, artifactAbs)) return proofDir;
643	  return null;
644	}
645	
646	async function readFileUtf8(p) {
647	  try {
648	    return (await readFile(p, 'utf8'));
649	  } catch (err) {
650	    throw wrapFsError(err, '读取文件');
651	  }
652	}
653	
654	function validateProof(proof) {
655	  if (proof === null || typeof proof !== 'object' || Array.isArray(proof)) {
656	    return '证明文件顶层必须是 JSON 对象';
657	  }
658	  const needString = ['proofVersion', 'artifactName', 'artifactDigest', 'fileName', 'generatedAt', 'signerKeyFingerprint'];
659	  for (const k of needString) {
660	    if (typeof proof[k] !== 'string' || proof[k].length === 0) {
661	      return `证明字段缺失或类型非法: ${k}`;
662	    }
663	  }
664	  if (!/^[0-9a-f]{64}$/i.test(proof.artifactDigest)) {
665	    return '证明中的 artifactDigest 不是合法的 SHA-256 十六进制摘要';
666	  }
667	  if (!/^[0-9a-f]{64}$/i.test(proof.signerKeyFingerprint)) {
668	    return '证明中的 signerKeyFingerprint 不是合法的 SHA-256 十六进制摘要';
669	  }
670	  if (typeof proof.size !== 'number' || !Number.isFinite(proof.size) || proof.size < 0) {
671	    return '证明字段缺失或类型非法: size';
672	  }
673	  if (!Array.isArray(proof.files)) return '证明字段缺失或类型非法: files';
674	  return validateFileEntries(proof.files);
675	}
676	
677	// 清单条目校验：proof.files 与 sbom.files 共用同一套规则。
678	function validateFileEntries(files) {
679	  const seen = new Set();
680	  for (const f of files) {
681	    if (f === null || typeof f !== 'object') return '清单条目必须是对象';
682	    if (typeof f.path !== 'string' || f.path.length === 0) return '清单条目 path 非法';
683	    if (f.path.includes('\\')) return `清单相对路径必须使用正斜杠: ${f.path}`;
684	    if (f.path.startsWith('/') || f.path.split('/').includes('..')) {
685	      return `清单相对路径越界: ${f.path}`;
686	    }
687	    if (seen.has(f.path)) return `清单路径重复: ${f.path}`;
688	    seen.add(f.path);
689	    if (!/^[0-9a-f]{64}$/i.test(f.sha256)) return `清单条目摘要非法: ${f.path}`;
690	    if (typeof f.size !== 'number' || !Number.isFinite(f.size) || f.size < 0) {
691	      return `清单条目大小非法: ${f.path}`;
692	    }
693	    if (typeof f.type !== 'string' || f.type.length === 0) return `清单条目类型非法: ${f.path}`;
694	  }
695	  return null;
696	}
697	
698	function validateSbom(sbom) {
699	  if (sbom === null || typeof sbom !== 'object' || Array.isArray(sbom)) {
700	    return 'SBOM 顶层必须是 JSON 对象';
701	  }
702	  for (const k of ['schemaVersion', 'artifactName', 'rootType']) {
703	    if (typeof sbom[k] !== 'string' || sbom[k].length === 0) {
704	      return `SBOM 字段缺失或类型非法: ${k}`;
705	    }
706	  }
707	  if (!Array.isArray(sbom.files)) return 'SBOM 字段缺失或类型非法: files';
708	  return validateFileEntries(sbom.files);
709	}
710	
711	// 返回差异列表；每条 {path, kind}。顶层摘要差异兜底。
712	function diffManifest(proof, currentSbom, currentDigest) {
713	  const mismatches = [];
714	  const proofFiles = new Map(proof.files.map((f) => [f.path, f]));
715	  const currentFiles = new Map(currentSbom.files.map((f) => [f.path, f]));
716	
717	  for (const [path, pf] of proofFiles) {
718	    const cur = currentFiles.get(path);
719	    if (!cur) {
720	      mismatches.push({ path, kind: 'missing' }); // 证明中存在、产物中已删除
721	      continue;
722	    }
723	    if (cur.sha256.toLowerCase() !== pf.sha256.toLowerCase()) {
724	      mismatches.push({ path, kind: 'content-modified' });
725	    } else if (cur.size !== pf.size) {
726	      mismatches.push({ path, kind: 'size-mismatch' });
727	    }
728	  }
729	  for (const path of currentFiles.keys()) {
730	    if (!proofFiles.has(path)) {
731	      mismatches.push({ path, kind: 'added' }); // 产物中新出现的文件
732	    }
733	  }
734	
735	  if (proof.artifactDigest.toLowerCase() !== currentDigest.toLowerCase() && mismatches.length === 0) {
736	    // 理论上不会发生（逐文件比对已覆盖），作为顶层摘要兜底。
737	    mismatches.push({ path: '.', kind: 'artifact-digest-mismatch' });
738	  }
739	  if (proof.fileName !== currentSbom.artifactName) {
740	    mismatches.push({ path: '.', kind: 'artifact-name-mismatch' });
741	  }
742	
743	  mismatches.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : a.kind < b.kind ? -1 : 1));
744	  return mismatches;
745	}
746	
747	// SBOM 清单与证明清单逐项比对；以证明为基准，kind 语义与 diffManifest 一致。
748	function diffSbomAgainstProof(sbom, proof) {
749	  const mismatches = [];
750	  const sbomFiles = new Map(sbom.files.map((f) => [f.path, f]));
751	  const proofFiles = new Map(proof.files.map((f) => [f.path, f]));
752	
753	  for (const [path, pf] of proofFiles) {
754	    const sf = sbomFiles.get(path);
755	    if (!sf) {
756	      mismatches.push({ path, kind: 'missing' }); // 证明中存在、SBOM 中缺失
757	      continue;
758	    }
759	    if (sf.sha256.toLowerCase() !== pf.sha256.toLowerCase()) {
760	      mismatches.push({ path, kind: 'content-modified' });
761	    } else if (sf.size !== pf.size) {
762	      mismatches.push({ path, kind: 'size-mismatch' });
763	    }
764	  }
765	  for (const path of sbomFiles.keys()) {
766	    if (!proofFiles.has(path)) {
767	      mismatches.push({ path, kind: 'added' }); // SBOM 中新出现的条目
768	    }
769	  }
770	  if (sbom.artifactName !== proof.artifactName) {
771	    mismatches.push({ path: '.', kind: 'artifact-name-mismatch' });
772	  }
773	
774	  mismatches.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : a.kind < b.kind ? -1 : 1));
775	  return mismatches;
776	}
777	
778	// ---------------------------------------------------------------------------
779	// CLI
780	// ---------------------------------------------------------------------------
781	
782	function parseArgs(argv) {
783	  const args = { _: [] };
784	  for (let i = 0; i < argv.length; i += 1) {
785	    const a = argv[i];
786	    if (a.startsWith('--')) {
787	      const key = a.slice(2);
788	      const next = argv[i + 1];
789	      if (next === undefined || next.startsWith('--')) {
790	        args[key] = true;
791	      } else {
792	        args[key] = next;
793	        i += 1;
794	      }
795	    } else {
796	      args._.push(a);
797	    }
798	  }
799	  return args;
800	}
801	
802	function usage() {
803	  return [
804	    'Prov Guard —— 软件供应链证明与完整性校验工具',
805	    '',
806	    '用法:',
807	    '  provguard keygen   --key-dir <dir> [--name <prefix>]',
808	    '  provguard generate --artifact <path> --key <private.pem> --out <dir>',
809	    '  provguard verify   --artifact <path> --proof <proof.json> \\',
810	    '                      --signature <proof.json.sig> --key <public.pem> \\',
811	    '                      [--sbom <sbom.json> --sbom-signature <sbom.json.sig>]',
812	    '',
813	    'generate 输出: proof.json / proof.json.sig / sbom.json / sbom.json.sig',
814	    '成功状态: VERIFIED；错误码见 README。',
815	  ].join('\n');
816	}
817	
818	function printMachineError(err) {
819	  const payload = {
820	    status: 'ERROR',
821	    errorCode: err instanceof ProvError ? err.code : 'INTERNAL_ERROR',
822	    message: err && err.message ? err.message : String(err),
823	  };
824	  if (err && err.details !== undefined) payload.details = err.details;
825	  return stableJsonStringify(payload);
826	}
827	
828	async function main(argv) {
829	  const args = parseArgs(argv);
830	  const command = args._[0];
831	
832	  try {
833	    if (!command || command === 'help' || command === '--help' || command === '-h') {
834	      process.stdout.write(`${usage()}\n`);
835	      return 0;
836	    }
837	
838	    if (command === 'keygen') {
839	      if (!args['key-dir']) {
840	        throw new ProvError(ERROR_CODES.USAGE_ERROR, '缺少必填参数 --key-dir');
841	      }
842	      const r = await keygen({ keyDir: args['key-dir'], name: args.name || 'provguard' });
843	      process.stdout.write(
844	        `${stableJsonStringify({ status: 'KEYGEN_OK', ...r })}\n`,
845	      );
846	      return 0;
847	    }
848	
849	    if (command === 'generate') {
850	      const missing = ['artifact', 'key', 'out'].filter((k) => typeof args[k] !== 'string');
851	      if (missing.length) {
852	        throw new ProvError(
853	          ERROR_CODES.USAGE_ERROR,
854	          `缺少必填参数: ${missing.map((m) => `--${m}`).join(', ')}`,
855	        );
856	      }
857	      const r = await generate({ artifact: args.artifact, key: args.key, out: args.out });
858	      process.stdout.write(
859	        `${stableJsonStringify({
860	          status: 'GENERATED',
861	          proofVersion: r.proofVersion,
862	          artifactDigest: r.artifactDigest,
863	          fileCount: r.fileCount,
864	          proofPath: r.proofPath,
865	          sbomPath: r.sbomPath,
866	          signaturePath: r.signaturePath,
867	          sbomSignaturePath: r.sbomSignaturePath,
868	        })}\n`,
869	      );
870	      return 0;
871	    }
872	
873	    if (command === 'verify') {
874	      const missing = ['artifact', 'proof', 'signature', 'key'].filter((k) => typeof args[k] !== 'string');
875	      if (missing.length) {
876	        throw new ProvError(
877	          ERROR_CODES.USAGE_ERROR,
878	          `缺少必填参数: ${missing.map((m) => `--${m}`).join(', ')}`,
879	        );
880	      }
881	      // --sbom 与 --sbom-signature 必须成对出现。
882	      const hasSbom = typeof args.sbom === 'string';
883	      const hasSbomSig = typeof args['sbom-signature'] === 'string';
884	      if (hasSbom !== hasSbomSig) {
885	        throw new ProvError(ERROR_CODES.USAGE_ERROR, '--sbom 与 --sbom-signature 必须成对提供');
886	      }
887	      const r = await verify({
888	        artifact: args.artifact,
889	        proof: args.proof,
890	        signature: args.signature,
891	        key: args.key,
892	        sbom: hasSbom ? args.sbom : undefined,
893	        sbomSignature: hasSbomSig ? args['sbom-signature'] : undefined,
894	      });
895	      process.stdout.write(`${stableJsonStringify(r)}\n`);
896	      return 0;
897	    }
898	
899	    throw new ProvError(ERROR_CODES.USAGE_ERROR, `未知子命令: ${command}`);
900	  } catch (err) {
901	    // stderr 仅输出机器可读 JSON；用法帮助走 stdout，避免污染错误流。
902	    process.stderr.write(`${printMachineError(err)}\n`);
903	    if (err instanceof ProvError && err.code === ERROR_CODES.USAGE_ERROR) {
904	      process.stdout.write(`\n${usage()}\n`);
905	    }
906	    return 1;
907	  }
908	}
909	
910	// 仅作为脚本直接运行时执行 main；被测试 import 时不执行。
911	if (process.argv[1] && realpathSync(process.argv[1]) === fileURLToPath(import.meta.url)) {
912	  main(process.argv.slice(2)).then((code) => {
913	    process.exitCode = code;
914	  });
915	}
916	
917	export { main, ProvError, ERROR_CODES as CODES };
918

